from collections import defaultdict, deque

def processQueriesOnCart(items, query):
    cart, alive = [], []
    pos = defaultdict(deque)  # id -> indices in cart, in arrival order

    def add(v):
        pos[v].append(len(cart))
        cart.append(v)
        alive.append(True)

    for v in items:
        add(v)
    for x in query:
        if x > 0:
            add(x)
        elif pos[-x]:
            alive[pos[-x].popleft()] = False
    return [v for v, ok in zip(cart, alive) if ok]

class Solution {
    public int[] processQueriesOnCart(int[] items, int[] query) {
        java.util.LinkedHashMap<Integer, Integer> ids = new java.util.LinkedHashMap<>();
        java.util.HashMap<Integer, java.util.ArrayDeque<Integer>> idsByVal = new java.util.HashMap<>();
        int[] cnt = {0};
        java.util.function.IntConsumer add = v -> {
            int id = cnt[0]++;
            ids.put(id, v);
            idsByVal.computeIfAbsent(v, k -> new java.util.ArrayDeque<>()).offer(id);
        };
        for (int v : items) add.accept(v);
        for (int q : query) {
            if (q > 0) add.accept(q);
            else {
                int v = -q;
                var dq = idsByVal.get(v);
                if (dq != null && !dq.isEmpty()) {
                    int id = dq.poll();
                    ids.remove(id);
                }
            }
        }
        int[] res = new int[ids.size()];
        int i = 0;
        for (int v : ids.values()) res[i++] = v;
        return res;
    }
}

class Solution {
public:
    vector<int> processQueriesOnCart(vector<int>& items, vector<int>& query) {
        list<int> lst;
        unordered_map<int, queue<list<int>::iterator>> byVal;
        auto add = [&](int v) {
            lst.push_back(v);
            auto it = prev(lst.end());
            byVal[v].push(it);
        };
        for (int v : items) add(v);
        for (int q : query) {
            if (q > 0) add(q);
            else {
                int v = -q;
                auto& dq = byVal[v];
                if (!dq.empty()) { lst.erase(dq.front()); dq.pop(); }
            }
        }
        return vector<int>(lst.begin(), lst.end());
    }
};
